import csv
import io
import re


def parse_csv(raw_csv: str):
    text = raw_csv.lstrip("\ufeff")
    reader = csv.reader(io.StringIO(text, newline=""), delimiter=";", quotechar='"', strict=False)

    records = []
    try:
        for row in reader:
            if row and any(value.strip() for value in row):
                records.append(row)
    except csv.Error:
        pass

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 7
    header_index = next(
        (i for i, row in enumerate(records) if len(row) == expected_width),
        None,
    )

    if header_index is None:
        header_index = 0

    def fit_width(row, width):
        row = list(row)
        if len(row) > width:
            row = row[:width - 1] + [";".join(row[width - 1:])]
        elif len(row) < width:
            row.extend([""] * (width - len(row)))
        return row

    columns = fit_width(records[header_index], expected_width)
    rows = [
        fit_width(row, len(columns))
        for row in records[header_index + 1:]
    ]

    return {"columns": columns, "rows": rows}
